    n = int(data[0]); m = int(data[1]); k = int(data[2])
    seats = sorted(int(x) for x in data[3:3 + m])
    if m == 1:
        gaps = [n]
    else:
        gaps = [seats[i + 1] - seats[i] for i in range(m - 1)]
        gaps.append(seats[0] + n - seats[-1])
    lo = 1
    hi = min(min(gaps), n // (m + k))
    while lo < hi:
        mid = (lo + hi + 1) // 2
        room = 0
        for g in gaps:
            room += g // mid
        if room - len(gaps) >= k:
            lo = mid
        else:
            hi = mid - 1
    print(lo)

main()

