import sys
from itertools import combinations
from math import comb

def main():
    data = sys.stdin.read().split()
    n = int(data[0]); m = int(data[1]); k = int(data[2])
    seats = sorted(int(x) for x in data[3:3 + m])
    taken = set(seats)
    free = [x for x in range(n) if x not in taken] if n <= 40 else []
    if free and comb(len(free), k) <= 20000:
        best = 0
        for extra in combinations(free, k):
            pts = sorted(seats + list(extra))
            t = len(pts)
            worst = n
            for i in range(t):
                d = (pts[(i + 1) % t] - pts[i]) % n
                d = min(d, n - d)
                if d < worst:
                    worst = d
            if worst > best:
                best = worst
        print(best)
        return
    gaps = [(seats[(i + 1) % m] - seats[i]) % n for i in range(m)] if m > 1 else [n]

    def ok(d):
        for g in gaps:
            if g < d:
                return False
        cnt = 0
        for g in gaps:
            pos = d
            while pos + d <= g:
                cnt += 1
                if cnt >= k:
                    return True
                pos += d
        return cnt >= k

    lo, hi = 1, n // 2
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if ok(mid):
            lo = mid
        else:
            hi = mid - 1
    print(lo)

main()
